::: {#tbl-c9-interacao .cell tbl-cap='Viés nacional e, nas 18 combinações de escolaridade e idade, viés absoluto médio e REQM média (pontos percentuais), em 100 amostras _opt-in_ do mundo com interação.'}

```{.r .cell-code}
ordem_c9 <- c("MrP, efeitos principais", "MrP, interação com pooling",
              "Duplamente robusto", "MrP com BART")
res_c9_int |>
  mutate(tipo = if_else(grupo == "Total", "nacional", "celulas")) |>
  group_by(metodo) |>
  summarise(vies_nacional = vies[tipo == "nacional"],
            vies_celulas = mean(abs(vies[tipo == "celulas"])),
            reqm_celulas = mean(reqm[tipo == "celulas"])) |>
  mutate(metodo = factor(metodo, levels = ordem_c9)) |>
  arrange(metodo) |>
  mutate(metodo = str_replace(as.character(metodo), "pooling", "_pooling_")) |>
  gt() |>
  fmt_markdown(metodo) |>
  fmt_number(-metodo, decimals = 2, dec_mark = ",") |>
  cols_label(metodo = "Método", vies_nacional = "Viés nacional",
             vies_celulas = "Viés nas células", reqm_celulas = "REQM nas células")
```

